// FamilyPlanner overdue/due-soon scan (instant-only). Mirrors the tested
// app/n8n/overdue-scan.code-node.js (scanBlob, instant path). Emits one item
// per email_queue row; on a quiet day emits ONE { _sentinel: true } item so the
// downstream chain (and the Heartbeat) never short-circuits on zero rows.
// Cadence: re-notify daily, no dedupe (decided 2026-06-23).
const EMAIL_TO_USER = { 'metalbee66@gmail.com': 'brad', 'dianaleshcheva@gmail.com': 'diana' };
const USER_TO_EMAIL = Object.fromEntries(Object.entries(EMAIL_TO_USER).map(([e, id]) => [id, e]));
const BASE_URL = 'https://metalbee66.github.io/financial-planner/';
const KIND_SUBJECT_PREFIX = { task_due_soon: 'Due soon', task_overdue: 'Overdue' };

function readAssignees(t) {
  if (!t) return [];
  if (Array.isArray(t.assignees) && t.assignees.length > 0) return t.assignees;
  if (typeof t.assignee === 'string' && t.assignee) return [t.assignee];
  return [];
}
function participantEmail(id) { return id ? (USER_TO_EMAIL[id] || null) : null; }
function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }
function shouldNotifyUser(prefs, kind) {
  if (!prefs) return true;
  if (prefs.master === false) return false;
  if (prefs.kinds && Object.prototype.hasOwnProperty.call(prefs.kinds, kind)) return prefs.kinds[kind] !== false;
  return true;
}
function isInstant(prefs, kind) {
  if (!shouldNotifyUser(prefs, kind)) return false;
  return ((prefs && prefs.mode) || 'instant') === 'instant';
}
function summaryFor(kind, task) {
  return kind === 'task_overdue' ? `"${task.name}" is past its due date.` : `"${task.name}" is due within 24 hours.`;
}
function sourceUrl(task) {
  if (task.projectId && task.id) return `${BASE_URL}#/projects/${task.projectId}/tasks/${task.id}`;
  if (task.projectId) return `${BASE_URL}#/projects/${task.projectId}`;
  return BASE_URL;
}

const blob = $input.first() ? $input.first().json : {};
const tasks = (blob && Array.isArray(blob.tasks)) ? blob.tasks : [];
const prefsMap = (blob && blob.prefs && typeof blob.prefs === 'object') ? blob.prefs : {};
const todayIso = $now.toFormat('yyyy-MM-dd');
const todayMs = Date.parse(todayIso);
const tomorrowMs = todayMs + 24 * 60 * 60 * 1000;
const nowIso = $now.toISO();

const out = [];
let seq = 0;
if (!Number.isNaN(todayMs)) {
  for (const t of tasks) {
    if (!t || !t.dueDate || readAssignees(t).length === 0) continue;
    if (t.status === 'done') continue;
    const dueMs = Date.parse(t.dueDate);
    if (Number.isNaN(dueMs)) continue;
    let kind = null;
    if (dueMs < todayMs) kind = 'task_overdue';
    else if (dueMs <= tomorrowMs) kind = 'task_due_soon';
    if (!kind) continue;
    for (const user of readAssignees(t)) {
      const prefs = prefsMap[user];
      if (!isInstant(prefs, kind)) continue;
      const email = participantEmail(user);
      if (!email) continue;
      const id = 'eq_scan_' + todayIso.replace(/-/g, '') + '_' + (seq++);
      const prefix = KIND_SUBJECT_PREFIX[kind];
      const summary = summaryFor(kind, t);
      const url = sourceUrl(t);
      out.push({ json: {
        _sentinel: false,
        _id: id,
        id,
        to: email,
        subject: `[Family Planner] ${prefix}${t.name ? ': ' + t.name : ''}`,
        bodyHtml: `<p>${esc(summary)}</p><p><a href="${esc(url)}">Open in Family Planner</a></p>`,
        kind,
        notificationId: null,
        taskId: t.id || null,
        projectId: t.projectId || null,
        sourceUrl: url,
        queuedAt: nowIso,
        sent: false,
        sentAt: null,
        attempts: 0,
        failed: false
      } });
    }
  }
}
// Quiet day: emit one sentinel so the chain + Heartbeat still fire once.
if (out.length === 0) return [{ json: { _sentinel: true } }];
return out;
